import { usePumpTokenHelper } from '@/hook/pump/usePumpTokenHelper'
import { PumpToken } from '@/type/pump'
import { formatNumberWithKMB, formatPercentage } from '@cetus/utils'
import { Flex, HTMLChakraProps, Text } from '@chakra-ui/react'
interface MarketCapBlockProps extends HTMLChakraProps<'div'> {
  pumpToken: PumpToken
  hasProgress?: boolean
}
export default function MarketCapBlock({ pumpToken, hasProgress = false, ...rest }: MarketCapBlockProps) {
  const { market_cap, raising_progress } = usePumpTokenHelper(pumpToken)
  return (
    <Flex align="center" {...rest}>
      <Text color="text_caption" fontWeight="500">
        ${formatNumberWithKMB(market_cap)}
      </Text>
      {hasProgress && (
        <Text color="text_caption" fontWeight="500">
          ( {formatPercentage(raising_progress)})
        </Text>
      )}
    </Flex>
  )
}
